int handle_route_nlmsg(struct sk_buff *in_skb, struct nlmsghdr *nlh,
                       struct netlink_ext_ack *extack)
{
    struct sk_buff *skb;
    int err = -EINVAL;

    skb = nlmsg_new(NLMSG_DEFAULT_SIZE, GFP_KERNEL);
    if (!skb)
        return -ENOMEM;

    err = parse_route_attrs(nlh, skb);
    if (err < 0)
        goto free_skb;

    err = setup_route_packet(skb, in_skb, nlh, extack);
    if (err < 0)
        goto free_skb;

    if (send_route_response(skb, nlh) < 0)
        err = -EIO;

free_skb:
    kfree_skb(skb);
    return err;
}

int handle_ip_route_info(struct sk_buff *in_skb, struct nlmsghdr *nlh, struct netlink_ext_ack *extack)
{
    struct sk_buff *skb;
    struct rtmsg *rtm;
    struct rtattr *rtattr;
    u32 source, destination, ifindex, userid;
    int ret;

    if (!in_skb || !nlh) {
        return -EINVAL;
    }

    skb = alloc_skb(NLMSG_GOODSIZE, GFP_KERNEL);
    if (!skb) {
        return -ENOMEM;
    }

    rtm = NLMSG_DATA(nlh);
    rtattr = RTM_RTA(rtm);
    int rtattrlen = RTM_PAYLOAD(nlh);

    source = 0;
    destination = 0;
    ifindex = 0;
    userid = 0;

    for (; RTA_OK(rtattr, rtattrlen); rtattr = RTA_NEXT(rtattr, rtattrlen)) {
        switch (rtattr->rta_type) {
            case RTA_SRC:
                source = *(u32 *)RTA_DATA(rtattr);
                break;
            case RTA_DST:
                destination = *(u32 *)RTA_DATA(rtattr);
                break;
            case RTA_OIF:
                ifindex = *(int *)RTA_DATA(rtattr);
                break;
            case RTA_UID:
                userid = *(uid_t *)RTA_DATA(rtattr);
                break;
            default:
                break;
        }
    }

    if (!source || !destination) {
        ret = -EINVAL;
        goto cleanup_skb;
    }

    if (rtm->rtm_type == RTN_UNICAST) {
        ret = ip_route_output_key(net, &route, &dest, source, 0, ifindex, 0);
    } else {
        ret = ip_route_output_key(net, &route, &dest, source, 0, ifindex, 0);
    }

    if (ret < 0) {
        goto cleanup_skb;
    }

    ret = skb_put(skb, sizeof(struct rtmsg));
    if (!ret) {
        ret = -ENOMEM;
        goto cleanup_route;
    }

    rtm = (struct rtmsg *)skb->data;
    rtm->rtm_type = RTN_UNICAST;
    rtm->rtm_table = RT_TABLE_MAIN;
    rtm->rtm_protocol = RTPROT_KERNEL;
    rtm->rtm_scope = RT_SCOPE_UNIVERSE;
    rtm->rtm_flags = 0;

    rtattr = (struct rtattr *)(rtm + 1);
    rtattr->rta_type = RTA_DST;
    rtattr->rta_len = sizeof(*rtattr) + sizeof(u32);
    *(u32 *)RTA_DATA(rtattr) = destination;

    rtattr = RTA_NEXT(rtattr, sizeof(*rtattr) + sizeof(u32));
    rtattr->rta_type = RTA_SRC;
    rtattr->rta_len = sizeof(*rtattr) + sizeof(u32);
    *(u32 *)RTA_DATA(rtattr) = source;

    rtattr = RTA_NEXT(rtattr, sizeof(*rtattr) + sizeof(u32));
    rtattr->rta_type = RTA_IIF;
    rtattr->rta_len = sizeof(*rtattr) + sizeof(int);
    *(int *)RTA_DATA(rtattr) = ifindex;

    rtattr = RTA_NEXT(rtattr, sizeof(*rtattr) + sizeof(int));
    rtattr->rta_type = RTA_OIF;
    rtattr->rta_len = sizeof(*rtattr) + sizeof(int);
    *(int *)RTA_DATA(rtattr) = route->dst.dev->ifindex;

    skb_reset_transport_header(skb);
    ret = netlink_unicast(net, skb, nlh->nlmsg_pid, MSG_DONTWAIT);
    if (ret < 0) {
        goto cleanup_route;
    }

    return 0;

cleanup_route:
    ip_rt_put(route);
cleanup_skb:
    kfree_skb(skb);
    return ret;
}

int handle_ip_route_info(struct sk_buff *in_skb, struct nlmsghdr *nlh,
                         struct netlink_ext_ack *extack)
{
    struct rtmsg *rtm = NLMSG_DATA(nlh);
    struct net *net = sock_net(SK_CAST(in_skb->sk));
    struct sk_buff *skb;
    int err;

    if (nlh->nlmsg_len < nlmsg_SPACE(sizeof(*rtm))) {
        NL_SET_ERR_MSG(extack, "Invalid message length");
        return -EINVAL;
    }

    skb = alloc_skb(NLMSG_GOOD_SIZE, GFP_KERNEL);
    if (!skb)
        return -ENOMEM;

    err = -ENOENT;
    switch (rtm->rtm_type) {
    case RTN_UNICAST:
        err = 0;
        break;
    case RTN_LOCAL:
        err = 0;
        break;
    case RTN_BROADCAST:
        err = 0;
        break;
    case RTN_MULTICAST:
        err = 0;
        break;
    default:
        break;
    }

    if (err < 0) {
        kfree_skb(skb);
        return err;
    }

    if (rtm->rtm_table) {
        NL_SET_ERR_MSG(extack, "Table value not supported");
        kfree_skb(skb);
        return -EOPNOTSUPP;
    }

    if (rtm->rtm_flags & RTM_F_NOTIFY) {
        /* Notification logic would be handled here */
    }

    skb->sk = (struct sock *)in_skb->sk;
    return skb->len;
}

int handle_ipv4_route_info(struct sk_buff *in_skb, struct nlmsghdr *nlh, struct netlink_ext_ack *extack)
{
    struct sk_buff *skb;
    struct iphdr *ip_header;
    int src_addr, dst_addr, if_index, user_id;
    int ret = 0;

    /* Parse the netlink message to extract routing attributes */
    if (nlh->nlmsg_len < NLMSG_HDRLEN) {
        return -EINVAL;
    }

    skb = alloc_skb(1500, GFP_KERNEL);
    if (!skb) {
        return -ENOMEM;
    }

    ip_header = (struct iphdr *)skb->data;

    if (!ip_header || ip_header->version != 4) {
        kfree_skb(skb);
        return -EINVAL;
    }

    src_addr = ip_header->saddr;
    dst_addr = ip_header->daddr;

    /* Retrieve interface index and user ID from the netlink message */
    if_index = 0;
    user_id = 0;

    if (if_index <= 0) {
        kfree_skb(skb);
        return -ENODEV;
    }

    if (user_id < 0) {
        kfree_skb(skb);
        return -EINVAL;
    }

    /* Determine if input or output interface is used for route lookup */
    if (if_index == 0) {
        ret = perform_output_route_lookup(src_addr, dst_addr, user_id, skb);
    } else {
        ret = perform_input_route_lookup(src_addr, dst_addr, if_index, user_id, skb);
    }

    if (ret < 0) {
        kfree_skb(skb);
        return ret;
    }

    /* Fill the socket buffer with routing information */
    ret = fill_route_information(skb, src_addr, dst_addr, if_index, user_id);
    if (ret < 0) {
        kfree_skb(skb);
        return ret;
    }

    /* Send the socket buffer back to user space */
    ret = send_route_info_to_user(skb, in_skb, nlh, extack);
    if (ret < 0) {
        kfree_skb(skb);
        return ret;
    }

    return 0;
}

int handle_ipv4_route_info(struct sk_buff *in_skb, struct nlmsghdr *nlh, struct netlink_ext_ack *extack)
{
    struct rtmsg *rtm = NLMSG_DATA(nlh);
    struct nlattr *tb[RTA_MAX];
    struct sk_buff *skb;
    struct rta_info *rinfo;
    int err;

    err = nlmsg_parse(nlh, sizeof(*rtm), tb, RTA_MAX - 1, NULL, extack);
    if (err < 0)
        return err;

    skb = alloc_skb(NLMSG_GOOD_SIZE, GFP_KERNEL);
    if (!skb)
        return -ENOMEM;

    rinfo = skb_put(skb, sizeof(*rinfo));
    rinfo->ifindex = rtm->rtm_oif;
    rinfo->src = *(__be32 *)RTA_DATA(tb[RTA_SRC]);
    rinfo->dst = *(__be32 *)RTA_DATA(tb[RTA_DST]);
    rinfo->table = rtm->rtm_table;

    if (rtm->rtm_flags & RTM_F_NOTIFY)
        rinfo->flags |= RT_NOTIFY;

    err = ip_route_output_key(&init_net, &rinfo->dest, &rinfo->dst, rinfo->src, rinfo->ifindex);
    if (err < 0) {
        kfree_skb(skb);
        return err;
    }

    nlh = nlmsg_put(skb, 0, 0, NLMSG_DONE, sizeof(*rinfo), 0);
    if (!nlh) {
        kfree_skb(skb);
        return -ENOBUFS;
    }

    netlink_unicast(skb, netlink_skb_parms(in_skb)->portid, 0);
    return 0;
}
